commands.command:
set -euo pipefail
test "$(uname -s)" = Darwin
export GIT_TERMINAL_PROMPT=0
WORK="$(mktemp -d /tmp/bloomml-web-style-fix.XXXXXX)"
trap 'rm -rf "$WORK"' EXIT
git clone --quiet --branch main https://github.com/MichalMatu/bloomml.git "$WORK/repo"
cd "$WORK/repo"
EXPECTED="cf1c4343a94862d75213093e7b528f56813c587b"
test "$(git rev-parse HEAD)" = "$EXPECTED"
test -z "$(git status --porcelain)"
cd web
pnpm install --offline --frozen-lockfile > "$WORK/install.log" 2>&1
node --input-type=module <<'JS'
import fs from 'node:fs';
import ts from 'typescript';
const files = ['src/pages/ipo-setup-page.tsx','src/pages/setup-page.tsx'];
const classes = new Set();
const accepted = new Set(['div','p','span','summary','ul','details','CardContent']);
const data = [];
function name(value) {
  return value.replace(/\[([^\]]+)\]/g, (_,v)=>' custom '+v)
    .replace(/[^a-zA-Z0-9]+/g,' ').trim().split(' ')
    .map((word,i)=>i===0 ? word : word[0].toUpperCase()+word.slice(1)).join('');
}
for (const file of files) {
  const source = fs.readFileSync(file,'utf8');
  const parsed = ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);
  const occurrences = [];
  function visit(node) {
    if (ts.isJsxElement(node)) {
      const el = node.openingElement;
      const oldTag = el.tagName.getText(parsed);
      const match=el.attributes.properties.find(x=>ts.isJsxAttribute(x)&&x.name.text==='className');
      if (match) {
        if(!accepted.has(oldTag)||!ts.isJsxAttribute(match)||!match.initializer||!ts.isStringLiteral(match.initializer)){
          throw new Error('UNSUPPORTED_STYLED_JSX|'+file+'|'+oldTag+'|'+el.getStart(parsed));
        }
        classes.add(match.initializer.text);
        occurrences.push({opening:el,closing:node.closingElement,attribute:match,tag:oldTag,value:match.initializer.text});
      }
    }
    ts.forEachChild(node,visit);
  }
  visit(parsed);
  if (occurrences.length !== (source.match(/\bclassName\s*=/g)||[]).length) throw new Error('SCOPE_MISMATCH|'+file);
  data.push({file,source,parsed,occurrences});
}
const named=new Map();
for (const style of [...classes].sort()) {
  const id = name(style);
  if(named.has(id))throw new Error('DUPLICATE_STYLE_NAME|'+id);
  named.set(id,style);
}
let total=0;
for(const {file,source,parsed,occurrences} of data){
  const patches=[];
  for(const occ of occurrences){
    const styleName=name(occ.value);
    patches.push([occ.opening.tagName.getStart(parsed),occ.opening.tagName.getEnd(),'AppStyled']);
    patches.push([occ.closing.tagName.getStart(parsed),occ.closing.tagName.getEnd(),'AppStyled']);
    patches.push([occ.attribute.getStart(parsed),occ.attribute.getEnd(),'as="'+occ.tag+'" layout="'+styleName+'"']);
    total++;
  }
  let output=source;
  for(const [s,e,v] of patches.sort((a,b)=>b[0]-a[0]))output=output.slice(0,s)+v+output.slice(e);
  if(file.includes('ipo-setup-page')){
    output=output.replace('AppPageHeader, AppSelectTrigger,','AppPageHeader, AppSelectTrigger, AppStyled,');
    output=output.replace('Card, CardContent, CardDescription, CardHeader, CardTitle','Card, CardDescription, CardHeader, CardTitle');
  } else {
    output=output.replace('  AppPageHeader,\n','  AppPageHeader,\n  AppStyled,\n');
  }
  fs.writeFileSync(file,output);
}
const object=[...named.entries()].sort(([a],[b])=>a.localeCompare(b))
  .map(([id,style])=>'  '+id+': '+JSON.stringify(style.replace('lg:grid-cols-[1fr_1fr_auto]','app-ipo-link-grid'))+',').join('\n');
const styled=[
'import { createElement, type HTMLAttributes, type ReactNode } from "react"',
'import { CardContent } from "@/components/ui/card"',
'',
'// Central, typed layout presets. Feature pages choose semantic tokens, never Tailwind.',
'const STYLES = {',
object,
'} as const',
'',
'type Layout = keyof typeof STYLES',
'type Tag = "div" | "p" | "span" | "summary" | "ul" | "details" | "CardContent"',
'',
'export function AppStyled({',
'  as = "div", layout, children, ...rest',
'}: Omit<HTMLAttributes<HTMLElement>, "className" | "style"> & {',
'  as?: Tag',
'  layout: Layout',
'  children?: ReactNode',
'}) {',
'  const className = STYLES[layout]',
'  if (as === "CardContent") {',
'    return <CardContent {...rest} className={className}>{children}</CardContent>',
'  }',
'  return createElement(as, { ...rest, className }, children)',
'}',
'',
].join('\n');
fs.writeFileSync('src/components/app-chrome/styled.tsx',styled);
const add=(f,oldVal,newVal)=>{
 const src=fs.readFileSync(f,'utf8');
 if(!src.includes(oldVal))throw Error('MISSING_ANCHOR|'+f+'|'+oldVal);
 fs.writeFileSync(f,src.replace(oldVal,newVal));
};
add('src/components/app-chrome/index.ts','export { AppErrorList } from "./errors"','export { AppErrorList } from "./errors"\nexport { AppStyled } from "./styled"');
add('src/components/app-chrome.tsx','  AppCanvasFrame,\n','  AppCanvasFrame,\n  AppStyled,\n');
add('src/config/allowed-surface.ts','  "AppCanvasFrame",\n','  "AppCanvasFrame",\n  "AppStyled",\n');
const css=fs.readFileSync('src/index.css','utf8');
fs.writeFileSync('src/index.css',css+'\n/* IPO operator link editor: named owner for its nonstandard third column. */\n@media (min-width: 64rem) {\n  .app-ipo-link-grid { grid-template-columns: 1fr 1fr auto; }\n}\n');
console.log('STYLE_REPAIR|'+total+' attributes|'+named.size+' unique typed presets');
JS
echo "STYLE_SOURCE_CHECK"
git diff --check
echo "WEB_GATE_START"
set +e
pnpm gate > "$WORK/web-gate.log" 2>&1
code=$?
set -e
echo "WEB_GATE_EXIT|$code"
tail -75 "$WORK/web-gate.log"
test "$code" -eq 0
cd ..
echo "CHANGED_FILES"
git status --short
echo "WEB_POSTCHECK|PASS"
test "$(git ls-remote --heads origin main | awk '{print $1}')" = "$EXPECTED"
git add web/src/pages/ipo-setup-page.tsx web/src/pages/setup-page.tsx web/src/components/app-chrome/styled.tsx web/src/components/app-chrome/index.ts web/src/components/app-chrome.tsx web/src/config/allowed-surface.ts web/src/index.css
git commit -m "refactor(web): centralize IPO layout tokens and restore strict lint gate"
git push origin HEAD:main
echo "PUSHED_SHA|$(git rev-parse HEAD)"
echo "WORKTREE_CLEAN|$(test -z "$(git status --porcelain)" && echo yes || echo no)"
